def _fit(selected, target):
    selected = set(selected or [])
    return len(selected & set(target)) / len(target) if target else 0.0

def recommend(answers, limit=3):
    """Return ranked matches and transparent evidence for submitted answers."""
    answers = answers or {}
    prof = answers.get("skill_levels", {}) or {}
    have = {s for s, level in prof.items() if level in ("Intermediate", "Advanced")}
    have |= {s for s in (answers.get("skills") or []) if s not in prof}
    interests = answers.get("interests") or []
    strengths = answers.get("strengths") or []
    styles = answers.get("work_styles") or []
    goals = answers.get("career_directions") or []
    ranked = []
    for career in CAREERS:
        skill_fit = _fit(have, career["skills"])
        interest_fit = _fit(interests, career["interests"])
        strength_fit = _fit(strengths, career["strengths"])
        style_fit = _fit(styles, career["work_styles"])
        goal_fit = 1.0 if career["slug"] in goals else (0.5 if not goals else 0.0)
        weighted_available = sum(WEIGHTS[k] for k, v in {
            "skills": bool(prof or answers.get("skills")), "interests": bool(interests),
            "strengths": bool(strengths), "work_styles": bool(styles), "goals": bool(goals)
        }.items() if v)
        raw = sum(WEIGHTS[k] * v for k, v in {"skills":skill_fit,"interests":interest_fit,
            "strengths":strength_fit,"work_styles":style_fit,"goals":goal_fit}.items())
        score = round(100 * raw / weighted_available) if weighted_available else 0
        matches = sorted(have & set(career["skills"]))
        gaps = [s for s in career["improve"] if s not in have]
        reasons = []
        if matches: reasons.append("Your current skills include " + ", ".join(matches[:3]))
        overlap = sorted(set(interests) & set(career["interests"]))
        if overlap: reasons.append("You selected interests in " + ", ".join(overlap[:2]))
        overlap = sorted(set(strengths) & set(career["strengths"]))
        if overlap: reasons.append("Your strengths include " + ", ".join(overlap[:2]))
        if not reasons: reasons.append("This is an exploratory match; add more assessment answers for a more personalized comparison.")
        item = deepcopy(career)
        item.update(score=score, matching_skills=matches, skill_gaps=gaps, reasons=reasons)
        ranked.append(item)
    ranked.sort(key=lambda c: (-c["score"], c["name"]))
    return ranked[:limit]

def all_careers():
    return deepcopy(CAREERS)

def career_by_slug(slug):
    return next((deepcopy(c) for c in CAREERS if c["slug"] == slug), None)
